{"command": "cd /workspace && python3 - <<'EOF'
import numpy as np, wave
def analyze(f, t0,t1, f0=261.63):
    w=wave.open(f); sr=w.getframerate(); n=w.getnframes(); ch=w.getnchannels()
    y=np.frombuffer(w.readframes(n),dtype='<i2').astype(float)/32768
    y=y.reshape(-1,ch).mean(axis=1)
    s=y[int(t0*sr):int(t1*sr)]
    S=np.abs(np.fft.rfft(s*np.hanning(len(s))))**2; fr=np.fft.rfftfreq(len(s),1/sr); tot=S.sum()
    mask=np.zeros(len(S),bool)
    for kk in range(1,50): mask |= (np.abs(fr-kk*f0)<0.08*f0)
    return 10*np.log10(S[~mask].sum()/tot), np.abs(s).max()
for t0,t1 in [(0.02,0.12),(0.12,0.25),(0.25,0.5),(0.5,1.0),(1.0,1.5),(1.5,1.95)]:
